const input = $input.first().json;
const mode = input.mode === 'full' ? 'full' : 'contact';
let t = String(input.text || '').replace(/\r\n/g, '\n');
const removed = {};
const count = (label) => { removed[label] = (removed[label] || 0) + 1; };
const sub = (re, replacement, label) => { t = t.replace(re, () => { count(label); return replacement; }); };
const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// 1. Contact details and identifiers (both modes). Done first so later steps can't mangle them.
sub(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL]', 'email');
sub(/https?:\/\/\S+|(?:www\.)?linkedin\.com\/\S+/gi, '[LINK]', 'link');
sub(/\b\d{13}\b/g, '[ID_NUMBER]', 'id_number');
// Phones: international (+27 82 555 1234) or local with a leading 0 (082 555 0101, 011-555-1234, (011) 555 1234).
// Requiring a + or a leading 0 stops dates, year ranges and reference numbers matching.
sub(/(?<![\d+])(?:\+\d{1,3}[\s-]?\(?\d{1,3}\)?[\s-]?\d{3}[\s-]?\d{3,4}|\(?0\d{2}\)?[\s-]?\d{3}[\s-]?\d{4})(?!\d)/g, '[PHONE]', 'phone');

if (mode === 'full') {
  // 2. The person's name: normally the first line that isn't a heading like "Curriculum Vitae".
  const nameLine = t.split('\n').map((l) => l.trim()).find((l) => l && !/curriculum|vitae|resum|^cv$/i.test(l));
  if (nameLine && nameLine.split(/\s+/).length <= 5 && !/[:@\d[]/.test(nameLine)) {
    const particles = ['van', 'der', 'de', 'du', 'von', 'la'];
    const parts = [nameLine, ...nameLine.split(/\s+/).filter((p) => p.length > 2 && !particles.includes(p.toLowerCase()))];
    for (const p of parts) sub(new RegExp(`\\b${escape(p)}\\b`, 'gi'), '[CANDIDATE]', 'name');
  }
  // 3. Whole lines that state protected or irrelevant attributes ("Gender: Female", "Date of birth: ...").
  sub(/^\s*(?:[-•*]\s*)?(gender|sex|race|ethnicity|population group|religion|marital status|date of birth|d\.o\.b\.?|dob|age|nationality|citizenship|disability|health|home language|dependants?|children|address|physical address|suburb)\s*[:\-].*$/gim, '[REMOVED]', 'attribute_line');
  // 4. Titles and gendered pronouns.
  sub(/\b(Mr|Mrs|Ms|Miss|Mx)\.?\s+/g, '', 'title');
  const pronouns = { he: 'they', she: 'they', him: 'them', his: 'their', her: 'their', hers: 'theirs', himself: 'themselves', herself: 'themselves' };
  t = t.replace(/\b(he|she|him|his|her|hers|himself|herself)\b/gi, (m) => {
    count('pronoun');
    const r = pronouns[m.toLowerCase()];
    return m[0] === m[0].toUpperCase() ? r[0].toUpperCase() + r.slice(1) : r;
  });
}
return [{ json: { redacted: t.replace(/\n{3,}/g, '\n\n').trim(), removed, mode } }];
